"C:\\Windows\\System32\\WindowsPowerShell\\v1.0\\powershell.exe" -Command 'Add-Type -AssemblyName System.Drawing
$flangeBitmap = New-Object System.Drawing.Bitmap(1600, 2400)
$flangeGraphics = [System.Drawing.Graphics]::FromImage($flangeBitmap)
$flangeGraphics.Clear([System.Drawing.Color]::White)
$flangeGraphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
$flangeFiles = @(Get-ChildItem -LiteralPath . -Filter '"'FL-*.svg' | Sort-Object Name)
"'$flangeIndex = 0
foreach ($flangeFile in $flangeFiles) {
    $flangeXml = New-Object System.Xml.XmlDocument
    $flangeXml.Load($flangeFile.FullName)
    $flangeRoot = $flangeXml.DocumentElement
    $flangeBox = @($flangeRoot.GetAttribute('"'viewBox').Split(' ') | ForEach-Object { [double]::Parse("'$_, [Globalization.CultureInfo]::InvariantCulture) })
    $flangeScale = [Math]::Min(760 / $flangeBox[2], 430 / $flangeBox[3])
    $flangeOffsetX = ($flangeIndex % 2) * 800 + 20 - $flangeBox[0] * $flangeScale
    $flangeOffsetY = [Math]::Floor($flangeIndex / 2) * 480 + 40 - $flangeBox[1] * $flangeScale
    foreach ($flangeNode in $flangeRoot.ChildNodes) {
        $flangePen = New-Object System.Drawing.Pen([System.Drawing.Color]::Black, [single][Math]::Max(0.7, 0.25 * $flangeScale))
        if ($flangeNode.HasAttribute('"'stroke-dasharray')) { "'$flangePen.Color = [System.Drawing.Color]::Gray; $flangePen.DashPattern = [single[]]@(10, 2, 1, 2) }
        switch ($flangeNode.LocalName) {
            '"'circle' {
                "'$flangeR = [double]$flangeNode.r * $flangeScale
                $flangeX = [double]$flangeNode.cx * $flangeScale + $flangeOffsetX
                $flangeY = [double]$flangeNode.cy * $flangeScale + $flangeOffsetY
                $flangeGraphics.DrawEllipse($flangePen, [single]($flangeX-$flangeR), [single]($flangeY-$flangeR), [single](2*$flangeR), [single](2*$flangeR))
            }
            '"'line' {
                "'$flangeGraphics.DrawLine($flangePen, [single]([double]$flangeNode.x1*$flangeScale+$flangeOffsetX), [single]([double]$flangeNode.y1*$flangeScale+$flangeOffsetY), [single]([double]$flangeNode.x2*$flangeScale+$flangeOffsetX), [single]([double]$flangeNode.y2*$flangeScale+$flangeOffsetY))
            }
            '"'polygon' {
                "'$flangePoints = @($flangeNode.points.Split('"' ') | ForEach-Object { "'$flangePair = $_.Split('"','); New-Object System.Drawing.PointF([single]([double]"'$flangePair[0]*$flangeScale+$flangeOffsetX), [single]([double]$flangePair[1]*$flangeScale+$flangeOffsetY)) })
                $flangeGraphics.FillPolygon([System.Drawing.Brushes]::Black, [System.Drawing.PointF[]]$flangePoints)
            }
            '"'text' {
                "'$flangeFont = New-Object System.Drawing.Font('"'Microsoft YaHei', [single]([double]"'$flangeNode.GetAttribute('"'font-size')*"'$flangeScale), [System.Drawing.FontStyle]::Regular, [System.Drawing.GraphicsUnit]::Pixel)
                $flangeTextSize = $flangeGraphics.MeasureString($flangeNode.InnerText, $flangeFont)
                $flangeTextX = [double]$flangeNode.x*$flangeScale+$flangeOffsetX
                $flangeTextY = [double]$flangeNode.y*$flangeScale+$flangeOffsetY
                if ($flangeNode.GetAttribute('"'text-anchor') -eq 'middle') { "'$flangeTextX -= $flangeTextSize.Width/2 }
                if ($flangeNode.GetAttribute('"'text-anchor') -eq 'end') { "'$flangeTextX -= $flangeTextSize.Width }
                if ($flangeNode.GetAttribute('"'dominant-baseline') -eq 'central') { "'$flangeTextY -= $flangeTextSize.Height/2 }
                $flangeGraphics.DrawString($flangeNode.InnerText, $flangeFont, [System.Drawing.Brushes]::Black, [single]$flangeTextX, [single]$flangeTextY)
                $flangeFont.Dispose()
            }
        }
        $flangePen.Dispose()
    }
    $flangeIndex++
}
$flangeBitmap.Save((Join-Path (Get-Location) '"'法兰盘预览.png'), [System.Drawing.Imaging.ImageFormat]::Png)
"'$flangeGraphics.Dispose()
$flangeBitmap.Dispose()
Write-Output "Rendered $flangeIndex DXF-derived previews."'

